CREATE TABLE IF NOT EXISTS app_users (id BIGSERIAL PRIMARY KEY, username VARCHAR(100) UNIQUE NOT NULL, password_hash VARCHAR(64) NOT NULL, full_name VARCHAR(200) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'USER', photo_path VARCHAR(500));
CREATE TABLE IF NOT EXISTS transactions (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES app_users(id), description VARCHAR(500) NOT NULL, amount BIGINT NOT NULL CHECK (amount > 0), type VARCHAR(20) NOT NULL, proof_path VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_transactions_user ON transactions(user_id);
